head.script:
// 테스트 설명, 유효성 값 설정
//  - column 샘플 관례 : hidden 은 Body Column 에만 설정 (설정 영역 con 옵션 미생성)
//  - 본 샘플(_2) : autoFit 너비 계산 / 여러 Cell 복사, 잘라내기 / contextMenu 기본 메뉴(ColumnShowAll) 축
//    true/false/미설정 표시, Header/Footer/SubTotal Cell, Column 구성, 병합된 Column, setColumnVisible()/getColumnVisible() 항목은 column_P_hidden_1 소유
scwin.tData = {
    "description" : "[column > P > hidden]<br/>Column 을 GridView 에 표시하지 않고 숨길지 설정합니다.",
    "validation" : [
        "autoFit 속성으로 Column 너비를 자동 조정할 때 숨겨진 Column 은 너비 계산에서 제외됩니다.",
        "여러 Cell 을 선택하여 복사하거나 잘라낼 때 숨겨진 Column 의 데이터는 제외됩니다.",
        "숨겨진 Column 이 있으면 contextMenu 의 기본 메뉴에 '전체 컬럼 숨기기 해제(ColumnShowAll)' 메뉴가 표시되며, 선택 시 숨겨진 Column 이 모두 표시됩니다."
    ]
}



scwin.onpageload = async function () {
    // Global DataList(gdl_boolean) 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정 (gdl_boolean : 1=미설정 / 2=true / 3=false)
    con_hidden.setValue("2");
    con_autoFit.setValue("allColumn");

    // comp 초기 생성
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// Body Column 정보 (Header Cell id, Body Column id)
scwin.colInfo = [
    { "header" : "h_code",  "id" : "code" },
    { "header" : "h_name",  "id" : "name" },
    { "header" : "h_qty",   "id" : "qty" },
    { "header" : "h_price", "id" : "price" },
    { "header" : "h_memo",  "id" : "memo" }
];



// comp 생성
//  - hidden(con 값) 은 name, price Body Column 2개에 설정 (code, qty, memo 는 미설정 대조용)
//  - 각 Column 너비 100px, GridView 너비 700px, contextMenu="true", useShiftKey="true" 고정
scwin.comp_init = async function () {
    // 기존 target / dataList / label 삭제
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove("dlt_bind");
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    // 조건 (미설정 옵션은 속성 자체를 넣지 않는다)
    let cHidden = con_hidden.getText();
    let cAutoFit = con_autoFit.getValue();

    // 테스트 정보 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] hidden 은 name, price Column 에 설정, 각 Column 너비 100px, GridView 너비 700px, contextMenu=true, useShiftKey=true\n[절차] 복사 : code Row 0 클릭 -> Shift + memo Row 1 클릭 -> Ctrl+C (잘라내기는 Ctrl+X) -> 붙여넣기 대상에 Ctrl+V 후 포커스 해제\n[절차] 메뉴 : Body Cell 마우스 우클릭 -> 전체 컬럼 숨기기 해제 메뉴 선택\n[확인] Column 너비 확인, 데이터 확인 버튼"', '', 'label1');

    let strNameSpace = $c.gcm.getNameSpace();

    // 바인딩 dataList
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="code" name="code" dataType="text"></w2:column>';
    strDlt += '<w2:column id="name" name="name" dataType="text"></w2:column>';
    strDlt += '<w2:column id="qty" name="qty" dataType="text"></w2:column>';
    strDlt += '<w2:column id="price" name="price" dataType="text"></w2:column>';
    strDlt += '<w2:column id="memo" name="memo" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    dlt_bind.setJSON([
        { "code" : "P-1001", "name" : "무선 키보드", "qty" : "12", "price" : "35000", "memo" : "입고 대기" },
        { "code" : "P-1002", "name" : "광마우스", "qty" : "30", "price" : "12000", "memo" : "정상" },
        { "code" : "P-1003", "name" : "모니터 받침대", "qty" : "7", "price" : "28000", "memo" : "재고 부족" }
    ], false);

    // GridView 속성
    let attrGrid = ' contextMenu="true" useShiftKey="true"';
    attrGrid += (cAutoFit === '') ? '' : ' autoFit="' + cAutoFit + '"';

    // 검증 대상 Body Column 속성
    let attrHidden = (cHidden === '') ? '' : ' hidden="' + cHidden + '"';

    // target 생성
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" id="" style="width:700px;height:150px;"' + attrGrid + '>';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="100" style="" inputType="text" id="h_code" value="code"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="h_name" value="name"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="h_qty" value="qty"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="h_price" value="price"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="h_memo" value="memo"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="100" style="" inputType="text" id="code" value=""></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="name" value=""' + attrHidden + '></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="qty" value=""></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="price" value=""' + attrHidden + '></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="memo" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// validation 1, 3 판정 출력 : 각 Column 의 화면 너비(Header Cell 기준, px) 와 표시 Column 너비 합계
scwin.btn_checkColumnWidth_onclick = function () {
    let arr = [];
    let sum = 0;
    for (let i = 0; i < scwin.colInfo.length; i++) {
        let th = document.querySelector("[id='" + target1.id + "_" + scwin.colInfo[i].header + "']");
        let width = th ? th.offsetWidth : 0;
        sum += width;
        arr.push(scwin.colInfo[i].id + " : " + width);
    }
    wf_body_bottom.getObj("scwin").setReturnValue("Column 너비 : " + arr.join(" / ") + " (합계 : " + sum + ")");
}



// validation 2 판정 출력 : 잘라내기 후 Row 0, 1 의 데이터 (숨겨진 Column 데이터는 잘라내기에서 제외)
scwin.btn_checkData_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    for (let r = 0; r < 2; r++) {
        let arr = [];
        for (let i = 0; i < scwin.colInfo.length; i++) {
            arr.push(scwin.colInfo[i].id + "=" + dlt_bind.getCellData(r, scwin.colInfo[i].id));
        }
        bottom.setReturnValue("Row " + r + " 데이터 : " + arr.join(", "));
    }
}



// validation 2 판정 출력 : 붙여넣기 대상에 붙여넣은 값(클립보드) - 행은 // , Cell 은 | 로 구분하여 표시
scwin.txa_pasteTarget_onchange = function (e) {
    // 역슬래시 이스케이프는 런타임에 변형되므로 문자 코드로 조립 (CR=13, LF=10, TAB=9)
    let CR = String.fromCharCode(13);
    let LF = String.fromCharCode(10);
    let TAB = String.fromCharCode(9);
    let pasted = txa_pasteTarget.getValue().split(CR).join("");
    if (pasted === "") {
        return;
    }
    let rows = pasted.split(LF).filter(function (row) {
        return row !== "";
    });
    for (let i = 0; i < rows.length; i++) {
        rows[i] = rows[i].split(TAB).join(" | ");
    }
    wf_body_bottom.getObj("scwin").setReturnValue("붙여넣은 값(클립보드) : " + rows.join(" // "));
}
